cmd:
set -euo pipefail; temp=$(mktemp -d); trap 'rm -rf "$temp"' EXIT; printf '{"private":true}
' > "$temp/package.json"; (cd "$temp" && bun add --dev @commitlint/cli@19.8.1 @commitlint/config-conventional@19.8.1 > /dev/null); printf "module.exports={extends:['@commitlint/config-conventional']};
" > "$temp/commitlint.config.cjs"; for name in checkpoint-message.txt result-message.txt; do file="$PWD/gate-reruns-input/$name"; "$temp/node_modules/.bin/commitlint" --cwd "$temp" --edit "$file"; printf 'FOLLOW_COMMITLINT %s
' "$name"; sha256sum "$file"; done
